import React, { useState } from 'react';
import MeshSphere from '../components/MeshSphere';
import { useMoods } from '../hooks/useStorage';

const MOODS = [
  { score:1, emoji:'😔', label:'Väldigt dåligt', hue1:0,   hue2:340, speed:0.2,  distort:0.85 },
  { score:2, emoji:'😟', label:'Dåligt',         hue1:20,  hue2:355, speed:0.28, distort:0.65 },
  { score:3, emoji:'😐', label:'Okej',           hue1:45,  hue2:30,  speed:0.4,  distort:0.45 },
  { score:4, emoji:'🙂', label:'Bra',            hue1:160, hue2:185, speed:0.55, distort:0.28 },
  { score:5, emoji:'😄', label:'Väldigt bra',    hue1:195, hue2:215, speed:0.8,  distort:0.15 },
];

export default function CheckIn({ setPage }) {
  const { addMood, todayChecked } = useMoods();
  const [hovered,  setHovered]    = useState(null);
  const [selected, setSelected]   = useState(null);
  const [note,     setNote]       = useState('');
  const [step,     setStep]       = useState('pick');

  const active = hovered ?? selected ?? 2;
  const m = MOODS[active];

  const handleSave = () => {
    const mood = MOODS[selected];
    addMood(mood.score, mood.emoji, mood.label, note);
    setStep('done');
  };

  if (todayChecked && step !== 'done') return <Done mood={MOODS[2]} title="Redan incheckad" sub="Kom tillbaka imorgon." setPage={setPage} />;
  if (step === 'done') return <Done mood={MOODS[selected]} title="Sparat" sub={`${MOODS[selected].emoji} ${MOODS[selected].label}`} setPage={setPage} />;

  if (step === 'note') return (
    <div style={{ minHeight:'100vh', background:'#120e0a', paddingBottom:96, overflow:'hidden', position:'relative' }}>
      <div style={{ position:'absolute', top:'-10%', left:'50%', transform:'translateX(-50%)', zIndex:0, opacity:0.85 }}>
        <MeshSphere size={360} speed={MOODS[selected].speed} distort={MOODS[selected].distort} hue1={MOODS[selected].hue1} hue2={MOODS[selected].hue2} />
      </div>
      <div style={{ position:'relative', zIndex:2, padding:'24px 22px', marginTop:'38vw', animation:'fadeUp .5s both' }}>
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(240,235,227,0.3)', marginBottom:6 }}>Du mår</p>
        <h2 style={{ fontFamily:'DM Serif Display,serif', fontSize:'clamp(28px,8vw,44px)', fontWeight:400, fontStyle:'italic', lineHeight:1.1, color:'rgba(240,235,227,0.9)', marginBottom:24 }}>
          {MOODS[selected].label}
        </h2>
        <div style={{ background:'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.08)', borderRadius:18, padding:'14px 16px', marginBottom:12, backdropFilter:'blur(10px)' }}>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(240,235,227,0.28)', marginBottom:10 }}>Notering · valfri</p>
          <textarea value={note} onChange={e=>setNote(e.target.value)} maxLength={255}
            placeholder="Vad hände idag?"
            style={{ width:'100%', background:'transparent', border:'none', color:'rgba(240,235,227,0.78)', fontSize:14, fontWeight:300, resize:'none', height:80, outline:'none', lineHeight:1.7 }} />
        </div>
        <button onClick={handleSave} style={{ width:'100%', padding:'14px', borderRadius:100, background:'rgba(240,235,227,0.9)', color:'#120e0a', fontSize:13, fontWeight:700, border:'none', marginBottom:8, boxShadow:'0 0 32px rgba(200,190,170,0.15)' }}>Spara →</button>
        <button onClick={()=>setStep('pick')} style={{ width:'100%', padding:'10px', fontSize:13, color:'rgba(240,235,227,0.28)' }}>← Ändra</button>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', background:'#120e0a', paddingBottom:96, overflow:'hidden', position:'relative' }}>
      {/* Orb changes colour with selection */}
      <div style={{ position:'absolute', top:'-10%', left:'50%', transform:'translateX(-50%)', zIndex:0, opacity:0.85, transition:'opacity .5s' }}>
        <MeshSphere size={380} speed={m.speed} distort={m.distort} hue1={m.hue1} hue2={m.hue2} key={active} />
      </div>

      <div style={{ position:'relative', zIndex:2, padding:'28px 22px 0' }}>
        <div style={{ display:'flex', justifyContent:'space-between' }}>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(240,235,227,0.28)' }}>Daglig check-in</p>
        </div>
      </div>

      <div style={{ position:'relative', zIndex:2, padding:'0 22px', marginTop:'38vw', animation:'fadeUp .7s .1s both' }}>
        <h1 style={{ fontFamily:'DM Serif Display,serif', fontSize:'clamp(32px,9vw,50px)', fontWeight:400, fontStyle:'italic', lineHeight:1.1, color:'rgba(240,235,227,0.88)', marginBottom:24 }}>
          Hur mår du<br/>idag?
        </h1>

        {/* Mood list — clean dark rows */}
        <div style={{ display:'flex', flexDirection:'column', gap:5, marginBottom:14 }}>
          {MOODS.slice().reverse().map((mood, i) => {
            const idx = 4 - i;
            const isSel = selected === idx;
            const isHov = hovered === idx;
            return (
              <button key={mood.score}
                onMouseEnter={() => setHovered(idx)} onMouseLeave={() => setHovered(null)}
                onClick={() => setSelected(idx)}
                style={{ display:'flex', alignItems:'center', gap:14, padding:'13px 16px', borderRadius:14, background: isSel||isHov ? 'rgba(255,255,255,0.08)' : 'rgba(255,255,255,0.03)', border:`1px solid ${isSel ? 'rgba(255,255,255,0.14)' : 'rgba(255,255,255,0.06)'}`, transition:'all .2s cubic-bezier(0.16,1,0.3,1)', transform: isHov&&!isSel ? 'translateX(4px)' : 'none' }}>
                <span style={{ fontSize:22 }}>{mood.emoji}</span>
                <div style={{ flex:1, textAlign:'left' }}>
                  <div style={{ fontSize:14, fontWeight: isSel?600:300, color: isSel?'rgba(240,235,227,0.92)':'rgba(240,235,227,0.55)', transition:'all .2s' }}>{mood.label}</div>
                </div>
                {(isSel||isHov) && <span style={{ fontSize:12, color:'rgba(240,235,227,0.25)' }}>→</span>}
              </button>
            );
          })}
        </div>

        <button onClick={()=>setStep('note')} disabled={selected===null}
          style={{ width:'100%', padding:'14px', borderRadius:100, background:selected!==null?'rgba(240,235,227,0.9)':'rgba(255,255,255,0.07)', color:selected!==null?'#120e0a':'rgba(240,235,227,0.22)', fontSize:13, fontWeight:700, border:'none', transition:'all .3s', boxShadow:selected!==null?'0 0 32px rgba(200,190,170,0.15)':'none' }}>
          Fortsätt →
        </button>
      </div>
    </div>
  );
}

function Done({ mood, title, sub, setPage }) {
  return (
    <div style={{ minHeight:'100vh', background:'#120e0a', paddingBottom:96, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', position:'relative', overflow:'hidden' }}>
      <div style={{ position:'absolute', top:'50%', left:'50%', transform:'translate(-50%,-60%)', zIndex:0, opacity:0.75 }}>
        <MeshSphere size={340} speed={mood.speed} distort={mood.distort} hue1={mood.hue1} hue2={mood.hue2} />
      </div>
      <div style={{ position:'relative', zIndex:2, textAlign:'center', padding:'0 24px' }}>
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(240,235,227,0.3)', marginBottom:10 }}>Check-in</p>
        <h2 style={{ fontFamily:'DM Serif Display,serif', fontSize:36, fontWeight:400, fontStyle:'italic', color:'rgba(240,235,227,0.88)', marginBottom:8 }}>{title}</h2>
        <p style={{ fontSize:15, color:'rgba(240,235,227,0.4)', marginBottom:36, fontWeight:300 }}>{sub}</p>
        <div style={{ display:'flex', gap:8, justifyContent:'center' }}>
          <button onClick={()=>setPage('history')} style={{ padding:'12px 22px', borderRadius:100, background:'rgba(240,235,227,0.9)', color:'#120e0a', fontSize:13, fontWeight:600, border:'none' }}>Historik</button>
          <button onClick={()=>setPage('home')} style={{ padding:'12px 22px', borderRadius:100, background:'rgba(255,255,255,0.06)', border:'1px solid rgba(255,255,255,0.08)', color:'rgba(240,235,227,0.5)', fontSize:13 }}>Hem</button>
        </div>
      </div>
    </div>
  );
}
